import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  TableContainer,
  TablePagination,
} from '@mui/material';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
// components
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';

export default function UserPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  const [search, setsearch] = useState('');
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [currentBookingList, setCurrentBookingList] = React.useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const { i18 } = useMyContext();

  const TABLE_HEAD = [
    { id: 'listingid', label: i18?.BOOKINGSLIST?.LISTING_ID || 'Listing Id', alignRight: false },
    { id: 'propertyName', label: i18?.BOOKINGSLIST?.PROPERTY_NAME || 'Property Name', alignRight: false },
    { id: 'category', label: i18?.BOOKINGSLIST?.CATEGORY || 'Category', alignRight: false },
    { id: 'night', label: i18?.BOOKINGSLIST?.NIGHTS || 'Nights', alignRight: false },
    { id: 'startdate', label: i18?.BOOKINGSLIST?.START_DATE || 'Start Date', alignRight: false },
    { id: 'enddate', label: i18?.BOOKINGSLIST?.END_DATE || 'End Date', alignRight: false },
    { id: 'currency', label: i18?.BOOKINGSLIST?.CURRENCY || 'Currency', alignRight: false },
    { id: 'fare', label: i18?.BOOKINGSLIST?.RATE || 'Rate', alignRight: false },
    { id: 'paiddate', label: i18?.BOOKINGSLIST?.PAID_DATE || 'Paid Date', alignRight: false },
    { id: 'status', label: i18?.BOOKINGSLIST?.STATUS || 'Status', alignRight: false },
  ];


  const fetchData = async () => {
    try {
      let url = `module/listing/booking/current?_page=${page}&_limit=${rowsPerPage}`;
      if (search) {
        url += `&search=${search}`;
        setPage(1);
      }
      const res = await axios.get(url);
      if (res.status === 200) {
        setCurrentBookingList(res.data.data[0].data);
        setTotalCount(res.data.data[0].totalCount[0]?.total || 0);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };
  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = currentBookingList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(1);
    setFilterName(event.target.value);
  };

  return (
    <>
      <Helmet>
        <title> Manage Trips | Admin panel </title>
      </Helmet>

      <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
        <Typography variant="h4" gutterBottom>

          {i18?.BOOKINGSLIST?.CURRENT_TRIPS || "Current Trips"}
        </Typography>
      </Stack>

      <Card>
        <UserListToolbar
          numSelected={selected.length}
          filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />

        <Scrollbar>
          <TableContainer sx={{ minWidth: 800 }}>
            <Table>
              <UserListHead
                order={order}
                orderBy={orderBy}
                headLabel={TABLE_HEAD}
                rowCount={currentBookingList.length}
                numSelected={selected.length}
                onRequestSort={handleRequestSort}
                onSelectAllClick={handleSelectAllClick}
              />

              <TableBody>
                {currentBookingList.map((row) => {
                  const { id, name } = row;
                  const selectedUser = selected.indexOf(name) !== -1;

                  return (
                    <TableRow
                      key={id}
                      tabIndex={-1}
                      role="checkbox"
                      selected={selectedUser}
                    >
                      <TableCell padding="checkbox">
                        {/* <Checkbox checked={selectedUser} onChange={(event) => handleClick(event, name)} /> */}
                      </TableCell>
                      <TableCell component="th" scope="row" padding="none">
                        {row.listingId}
                      </TableCell>
                      <TableCell align="left">
                        <a
                          target="_blank"
                          rel="noreferrer"
                          style={{ cursor: 'pointer', textDecoration: 'none', color: 'black', whiteSpace: 'nowrap' }}
                        >
                          {' '}
                          {row?.propertyName}
                        </a>
                      </TableCell>
                      <TableCell align="left">{row.propertyCategoryName}</TableCell>
                      <TableCell align="left">{row.bookedHours?.nights}</TableCell>
                      <TableCell align="left">{DateFormat(row?.bookedDates?.start)}</TableCell>
                      <TableCell align="left">{DateFormat(row?.bookedDates?.end)}</TableCell>
                      <TableCell align="left">{row.currency}</TableCell>
                      <TableCell align="left">{row.fareAmount}</TableCell>
                      <TableCell align="left">{DateFormat(row?.paidDate)}</TableCell>
                      <TableCell align="left">{row.status}</TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>

              {currentBookingList.length === 0 && (
                <TableBody>
                  <TableRow>
                    <TableCell align="center" colSpan={12} sx={{ py: 3 }}>
                      <Paper
                        sx={{
                          textAlign: 'center',
                        }}
                      >
                        <Typography variant="h6" paragraph>

                          {i18?.BOOKINGSLIST?.NO_DATA_FOUND || "No Data Found"}
                        </Typography>
                      </Paper>
                    </TableCell>
                  </TableRow>
                </TableBody>
              )}
            </Table>
          </TableContainer>
        </Scrollbar>

        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={totalCount || '0'}
          rowsPerPage={rowsPerPage}
          page={page - 1}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          sx={{
            '.MuiTablePagination-selectLabel': {
              marginTop: '12px',
            },
            '.MuiTablePagination-displayedRows': {
              marginTop: '12px',
            },
            '.MuiTablePagination-actions': {
              marginBottom: '6px',
            }
          }}
        />
      </Card>
    </>
  );
}
